canvas.addEventListener('mousedown',e=>{if(state!=='playing'||document.pointerLockElement!==canvas)return;if(e.button===0){mouseDown=true;melee();}if(e.button===2){mouseRight=true;chargeTime=0;if(rogueMode){alternateAttack();return;}audioTone(180,.15,'sine',.025,1.3);}if(e.button===1)e.preventDefault();});
window.addEventListener('mouseup',e=>{if(e.button===0)mouseDown=false;if(e.button===2){if(!rogueMode&&mouseRight&&state==='playing')releaseHeavy();mouseRight=false;chargeTime=0;}});
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Tab','AltLeft','AltRight'].includes(e.code))e.preventDefault();if(e.code==='Escape'){if(state==='playing'||state==='paused')pauseGame();return;}if(rogueMode&&expeditionKey(e))return;if(state!=='playing')return;input[e.code]=true;if(e.repeat)return;if(e.code==='ShiftLeft'||e.code==='ShiftRight')dodge();if(e.code==='Space'&&grounded){velocityY=9;grounded=false;audioTone(110,.1,'triangle',.02);}if(e.code==='KeyQ')burst();if(e.code==='KeyE')useAbility();if(e.code==='KeyC')parry();if(e.code==='KeyG')grapple();if(e.code==='KeyF')interact();if(e.code==='KeyH')heal();if(e.code==='KeyX')useUtility();if(e.code==='KeyM'||e.code==='Tab')toggleTacticalMap();if(e.code==='KeyT')cycleExit();if(e.code==='KeyB')toggleTacticalMap();if(e.code==='KeyR')evolve();if(e.code==='Digit1')switchWeapon(0);if(e.code==='Digit2')switchWeapon(1);});
window.addEventListener('keyup',e=>{input[e.code]=false;});window.addEventListener('blur',()=>{if(state==='playing'||lockPending)pauseGame();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&(state==='playing'||lockPending))pauseGame();});
