 if(loadout[activeWeapon]==='spear'){const d=new THREE.Vector3(Math.sin(player.group.rotation.y),0,Math.cos(player.group.rotation.y));drawTrail(p,p.clone().addScaledVector(d,w.reach),color,.16,.06);}
